head.script:
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSchDate;
scwin.gJobTitle = js_jobtitl;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gISUR_CD;
scwin.gCOM_NM;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_Grid.getCellData(Number(row), "ISUR_CD");
        scwin.gComAbbrv = dts_Grid.getCellData(Number(row), "COM_ABBRV");
        scwin.gSchDate = edt_SchDate.getValue();
        gDtecDate = dts_Grid.getCellData(Number(row), "DTEC_DD");
        if (colid === "COM_ABBRV") {
            // 회사정보
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === "EXCNT_DISCLS_CORP_YN") {
            // 공시우수
            let url = "/dsclmgt/ULDSTF37301.gfm";
            url += "?POPUPMODE";
            let winTitle = "우수공시법인현황";
            await $c.frame.CreateFrame("ULDSTF37301", url, winTitle, 100, 100, 830, 510, "window", 0, 0, true);
        } else if (colid === "NFAITHDISCLS_CORP_YN") {
            // 불성실공시
            let url = "/dsclmgt/ULDSTF37401.gfm";
            url += "?POPUPMODE";
            let winTitle = "불성실공시법인 현황(최근3년)";
            await $c.frame.CreateFrame("ULDSTF37401", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
        } else if (colid === "DISCLS_EDU_COMPLT_COND_YN") {
            // 공시교육
            let url = "/dsclmgt/ULDSTF37403.gfm";
            url += "?POPUPMODE";
            let winTitle = "공시책임자 및 공시담당자 교육이수 현황(최근2년)";
            await $c.frame.CreateFrame("ULDSTF37403", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
        } else if (colid === "ADMISU_YN") {
            // 관리종목
            let url = "/dsclmgt/ULDSTF37404.gfm";
            url += "?POPUPMODE";
            let winTitle = "관리종목 지정 현황(최근3년)";
            await $c.frame.CreateFrame("ULDSTF37404", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
        } else if (colid === "INVSTCAUTN_REMND_ISU_YN") {
            // 투자주의환기종목
            let url = "/dsclmgt/ULDSTF37405.gfm";
            url += "?POPUPMODE";
            let winTitle = "투자주의 환기종목 지정 현황(최근3년)";
            await $c.frame.CreateFrame("ULDSTF37405", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
        } else if (colid === "AUDT_OPIN_OPT_YN") {
            // 감사의견
            let url = "/dsclmgt/ULDSTF37402.gfm";
            url += "?POPUPMODE";
            let winTitle = "최근 사업연도 감사의견 현황(최근1년)";
            await $c.frame.CreateFrame("ULDSTF37402", url, winTitle, 50, 50, 830, 520, "window", 0, 0, true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF37400.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "면제대상현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        let chkVal = dts_Grid.getCellData(Number(row), "CHK_FLAG");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_assignDD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name btn_assignAll_onclick
 * @description 「선택법인일괄지정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_assignAll_onclick = async function() {
    try {
        let selectedApplDate = "";
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        selectedApplDate = edt_assignDD.getValue();
        if (vCurDate >= selectedApplDate) {
            await $c.win.alert("오늘 날짜 이후만 가능");
            return false;
        } else {
            if (scwin.isChecked()) {
                let msg = "체크된 항목을 반영일 기준으로 일괄 지정/해제 처리 하시겠습니까?";
                if (confirm(msg)) {
                    await scwin.doBatch4ByPass();
                }
            } else {
                await $c.win.alert('일괄 지정/해제를 위해 체크된 항목이 없습니다.');
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.btn_assignAll_onclick" });
    }
};

/**
 * @method
 * @name btn_selAll_onclick
 * @description 「대상일괄선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_selAll_onclick = function() {
    try {
        let sameYN = "";
        let msg = "기존 체크 여부를 무시하고, 상장원부 일치여부가 'N'인것만 체크합니다.\r\n계속 진행 하시겠습니까?";
        if (confirm(msg)) {
            dts_Grid.setBroadcast(false);
            for (let i = 1; i <= dts_Grid.getRowCount(); i++) {
                sameYN = dts_Grid.getCellData(Number(i), "LIST_ORG_YN");
                if (sameYN === "N") {
                    dts_Grid.setCellData(eval(i, 1), "CHK_FLAG");
                } else {
                    dts_Grid.setCellData(eval(i, 0), "CHK_FLAG");
                }
            }
            dts_Grid.setBroadcast(true, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37400.btn_selAll_onclick" });
    }
};

/**
 * @method
 * @name tr_batch_OnSuccess
 * @description tr batch On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_batch_OnSuccess = async function() {
    try {
        await $c.win.alert('일괄지정 처리가 완료되었습니다');
        dts_Grid.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37400.tr_batch_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 페이지 로딩 시 필요한 변수 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 조회일자 오늘로 셋팅
    /*
    	2020.09.03 KBoY
    	상장일은 무조건 3년전 7월1일 부터 당해 6월 30일까지 인데, 나머지(불성실, 관리종목 등)은 3년전 7월1일 부터 조회일까지로 두개가 불일치하여
    	혼돈의 소지가 있어 날짜를 수정할 수 없게 바꾸고, 조회일자도 7월 1일로 고정되게 만든다.(현업 요청)
     */
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate < (vCurDate.substr(0, 4) + '0601')) edt_SchDate.setValue((vCurDate.substr(0, 4) - 1) + '0701');

    else edt_SchDate.setValue(vCurDate.substr(0, 4) + '0701');

    // setObjectValue(rdo_EXT_ID, '1');

    if (scwin.gJobTitle === '09') {
        pnl_batch.show("");
    } else {
        pnl_batch.hide();
    }
};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vISUR_CD = txb_isur_cd.getValue();
    const vSCH_DD = edt_SchDate.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    //        var vEXT_ID = getObjectValue(rdo_EXT_ID);

    let url;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCH_DD=" + vSCH_DD;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    //        url += "&EXT_ID=" + vEXT_ID;
    url += "&SCREN_ID=" + "ULDSTF37400.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/ByPass.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name doBatch4ByPass
 * @description 일괄 지정/해제 수행 2020.09.08 KBoY
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doBatch4ByPass = async function() {
    const dtec_dd = dts_Grid.getCellData(1, "DTEC_DD");
    let msg = "금일 기 신청한 일괄신청 지정/해제 건은 모두 삭제됩니다.\r\n계속 진행하시겠습니까? ";
    if (confirm(msg)) {
        if (scwin.setCommonInfo()) {
            tr_batch.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_tr_batch",
                action : "/ByPass.do",
                ref : "dts_Grid",
                target : "tr_batch=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        } else {
            await $c.win.alert('지정일 세팅중 오류 발생');
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCommonInfo
 * @description 지정일&처리자 세팅. 전체에 넣어주면 전체 row가 업데이트 된걸로 인식함. 그래서 체크된 row만 넣어줌 2020.09.08 KBoY
 * @returns {void}
 * @hidden N
 */
scwin.setCommonInfo = function() {
    const assignDD = edt_assignDD.getValue();
    let chkVal = 0;
    dts_Grid.setBroadcast(false);
    for (i = 1; i <= dts_Grid.getRowCount(); i++) {
        chkVal = dts_Grid.getCellData(i, "CHK_FLAG");
        if (chkVal === 1) {
            dts_Grid.setCellData(i, "assign_dd", assignDD);
            dts_Grid.setCellData(i, "reg_id", scwin.gEmpNo);
        }
    }
    dts_Grid.setBroadcast(true, true);
    return true;
};

/**
 * @method
 * @name isChecked
 * @description is Checked 처리
 * @returns {void}
 * @hidden N
 */
scwin.isChecked = function() {
    let cnt = 0;
    let chkVal = 0;
    for (i = 1; i <= dts_Grid.getRowCount(); i++) {
        chkVal = dts_Grid.getCellData(i, "CHK_FLAG");
        if (chkVal === 1) cnt++;
    }
    if (cnt === 0) return false;

    else return true;
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
